import{_ as s,a0 as a,w as p,s as l,ao as k,I as i,x as o,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Docker 在安全組件、實時容器遷移方面的進展 | LCTT x X-CMD","titleTemplate":false,"description":"Docker 在安全組件、實時容器遷移方面的進展 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Docker 在安全組件、實時容器遷移方面的進展 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Docker 在安全組件、實時容器遷移方面的進展 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150818 Docker Working on Security Components Live Container Migration","title":"Docker 在安全組件、實時容器遷移方面的進展","tag":"201509","desc":""},"relativePath":"201509/20150818 Docker Working on Security Components Live Container Migration.md","filePath":"[post].md"}'),c={name:"201509/20150818 Docker Working on Security Components Live Container Migration.md"};function D(T,e,m,C,u,d){const t=a("Link");return p(),l("div",null,[e[13]||(e[13]=k('<h1 id="docker-在安全組件、實時容器遷移方面的進展" tabindex="-1">Docker 在安全組件、實時容器遷移方面的進展 <a class="header-anchor" href="#docker-在安全組件、實時容器遷移方面的進展" aria-label="Permalink to “Docker 在安全組件、實時容器遷移方面的進展”">​</a></h1><p><img src="http://www.eweek.com/imagesvr_ce/1905/290x195DockerMarianna.jpg" alt="Docker Container Talk"></p><p><strong>這是 Docker 開發者在 Containercon 上的演講，談論將來的容器在安全和實時遷移方面的創新</strong></p><p>來自西雅圖的消息。當前 IT 界最熱的詞彙是“容器”，美國有兩大研討會：Linuxcon USA 和 Containercon，後者就是為容器而生的。</p><p>Docker 公司是開源 Docker 項目的商業贊助商，本次研討會這家公司有 3 位高管帶來主題演講，但公司創始人 Solomon Hykes 沒上場演講。</p><p>Hykes 曾在 2014 年的 Linuxcon 上進行過一次主題演講，但今年的 Containeron 他只坐在觀眾席上。而工程部高級副總裁 Marianna Tessel、Docker 首席安全官 Diogo Monica 和核心維護員 Michael Crosby 為我們演講 Docker 新增的功能和將來會有的功能。</p><p>Tessel 強調 Docker 現在已經被很多世界上大型組織用在生產環境中，包括美國政府。Docker 也被用在小環境中，比如樹莓派，一塊樹莓派上可以跑 2300 個容器。</p><p>“Docker 的功能正在變得越來越強大，而部署方法變得越來越簡單。”Tessel 在會上説道。</p><p>Tessel 把 Docker 形容成一艘遊輪，內部由強大而複雜的機器驅動，外部為乘客提供平穩航行的體驗。</p><p>Docker 試圖解決的領域是簡化安全配置。Tessel 認為對於大多數用户和組織來説，避免網絡漏洞所涉及的安全問題是一個乏味而且複雜的過程。</p><p>於是 Docker Content Trust 就出現在 Docker 1.8 release 版本中了。安全項目領導 Diogo Mónica 中加入了 Tessel 的台上討論，説安全是一個難題，而 Docker Content Trust 就是為解決這個難道而存在的。</p><p>Docker Content Trust 提供一種方法來驗證一個 Docker 應用是否可信，以及多種方法來限制欺騙和病毒注入。</p><p>為了證明他的觀點，Monica 做了個現場示範，演示 Content Trust 的效果。在一個實驗中，一個網站在更新過程中其 Web App 被人為攻破，而當 Content Trust 啓動後，這個黑客行為再也無法得逞。</p><p>“不要被這個表面上簡單的演示欺騙了，”Tessel 説道，“你們看的是最安全的可行方案。”</p><p>Docker 以前沒有實現的領域是實時遷移，這個技術在 VMware 虛擬機中叫做 vMotion，而現在，Docker 也實現了這個功能。</p><p>Docker 首席維護員 Micheal Crosby 在台上做了個實時遷移的演示，Crosby 把這個過程稱為快照和恢復：首先從運行中的容器拿到一個快照，之後將這個快照移到另一個地方恢復。</p><p>一個容器也可以克隆到另一個地方，Crosby 將他的克隆容器稱為“多利”，就是世界上第一隻被克隆出來的羊的名字。</p><p>Tessel 也花了點時間聊了下 RunC 組件，這是個正在被 Open Container Initiative 作為多方開發的項目，目的是讓它可以從 Linux 擴展到包括 Windows 和 Solaris 在內的多種操作系統。</p><p>Tessel 總結説她不知道 Docker 的未來是什麼樣，但對此抱非常樂觀的態度。</p><p>“我不確定未來是什麼樣的，但我很確定 Docker 會在這個世界中脱穎而出”，Tessel 説的。</p><p>Sean Michael Kerner 是 eWEEK 和 InternetNews.com 網站的高級編輯，可通過推特 @TechJournalist 關注他。</p><hr>',22)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),n(t,{href:"http://www.eweek.com/virtualization/docker-working-on-security-components-live-container-migration.html"},{default:r(()=>[...e[0]||(e[0]=[o("http://www.eweek.com/virtualization/docker-working-on-security-components-live-container-migration.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),n(t,{href:"http://www.eweek.com/cp/bio/Sean-Michael-Kerner/"},{default:r(()=>[...e[2]||(e[2]=[o("Sean Michael Kerner",-1)])]),_:1}),e[6]||(e[6]=o(" 譯者：",-1)),n(t,{href:"https://github.com/bazz2"},{default:r(()=>[...e[3]||(e[3]=[o("bazz2",-1)])]),_:1}),e[7]||(e[7]=o(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原創翻譯，",-1)),n(t,{href:"https://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[o("Linux中國",-1)])]),_:1}),e[12]||(e[12]=o(" 榮譽推出",-1))])])}con